  function openEntry(raffle=activeRaffle){if(!user){setModal('auth');return}setEntryForm({name:profile?.name||user.displayName||'',email:profile?.email||user.email||'',phone:profile?.phone||'',contact:profile?.contact||'',address:profile?.address||'',paymentMethod:'',paymentAccount:'',couponCode:'',ticketCount:'1',raffleId:raffle?.id||availableRaffles[0]?.id||''});setModal('entry')}
